#!/bin/sh
# Validates the first line of a commit message against Conventional Commits.
# Usage: sh scripts/check_commit_msg.sh <path-to-commit-msg-file>
set -eu

msg_file="${1:?commit message file required}"
first_line=$(head -n 1 "$msg_file")

# Allow merge, revert and fixup/squash commits generated by git.
case "$first_line" in
  Merge\ *|Revert\ *|fixup!\ *|squash!\ *) exit 0 ;;
esac

pattern='^(feat|fix|docs|style|refactor|perf|test|build|ci|chore|revert)(\([a-z0-9._/-]+\))?!?: .{1,}$'

if ! printf '%s' "$first_line" | grep -Eq "$pattern"; then
  echo "Invalid commit message: \"$first_line\"" >&2
  echo "Expected Conventional Commits: <type>(<scope>)?: <description>" >&2
  echo "Types: feat fix docs style refactor perf test build ci chore revert" >&2
  exit 1
fi
